defmodule Tuist.Docs.OgImage do
  @moduledoc """
  Phoenix component that renders documentation OG image cards as HTML.
  The rendered HTML is passed to Carta for screenshot capture via BrowseChrome.

  The layout is the Figma "docs-card" (1920x1080, near-black ground): the
  page title and description top-left, the Tuist wordmark with a "Docs"
  suffix bottom-left, and the page's category bottom-right. The footer's
  mark and words are the design's own outlines, inlined as SVG so they
  never depend on a font; the title, description and category are live
  text in Inter.
  """
  use Phoenix.Component

  alias Phoenix.HTML.Safe

  # Two lines of the 136px title and three of the 56px description fit
  # above the footer at the 1768px content width.
  @max_title_length 46
  @max_description_length 120

  attr :title, :string, required: true
  attr :description, :string, default: nil
  attr :category, :string, default: "Docs"
  attr :font_data_uri, :string, required: true
  attr :georgian_font_data_uri, :string, required: true

