            font-weight: 100 900;
            src: url(<%= @font_data_uri %>) format('woff2');
          }
          @font-face {
            font-family: 'Noto Sans Georgian';
            font-style: normal;
            font-weight: 100 900;
            src: url(<%= @georgian_font_data_uri %>) format('woff2');
            unicode-range: U+0589, U+10A0-10FF, U+1C90-1CBA, U+1CBD-1CBF, U+205A, U+2D00-2D2F, U+2E31;
          }
          /* Hex rather than Noora tokens: headless Chrome does not resolve
             oklch() reliably here. #0E0E0E is the near-black ground,
             #FDFDFD the primary label, #C7CCD1 the secondary one. */
          * { margin: 0; padding: 0; box-sizing: border-box; }
          html, body {
            width: 1920px;
            height: 1080px;
            overflow: hidden;
            font-family: 'Inter Variable', 'Noto Sans Georgian', sans-serif;
            color-scheme: dark;
            background: #0E0E0E;
          }
          .content {
            position: absolute;
            left: 76px;
            top: 320px;
            width: 1768px;
            display: flex;
            flex-direction: column;
            gap: 67px;
          }
          .title {
            font-size: 136px;
            font-weight: 400;
            line-height: 136px;
            letter-spacing: -0.03em;
            color: #FDFDFD;
            overflow-wrap: break-word;
          }
          .description {
            font-size: 56px;
            font-weight: 400;
            line-height: 70px;
            letter-spacing: -0.01em;
            color: #C7CCD1;
            overflow-wrap: break-word;
          }
          .footer {
            position: absolute;
            inset: 0;
            width: 1920px;
            height: 1080px;
          }
          .category {
            position: absolute;
            right: 77px;
            bottom: 66px;
            font-size: 58px;
            font-weight: 400;
            line-height: 58px;
            letter-spacing: -0.02em;
            color: #FDFDFD;
            white-space: nowrap;
          }
        </style>
      </head>
      <body>
        <div class="content">
          <div class="title">{truncate(@title, @max_title_length)}</div>
          <div :if={@description} class="description">
